OPENQASM 3.0;
include "stdgates.inc";

// Declarations
qubit[4] q;
bit[2] c;

// 1. Basic Gates & Parameters
h q[0];
rx(pi/2) q[1];
rz(0.123) q[2];

// 2. Modifiers (Inverse, Control, Power)
inv @ s q[3];
ctrl(2) @ x q[0], q[1], q[2];
pow(0.5) @ y q[3];

// 3. Global Barrier
barrier q;

// 4. Entanglement & Standard Multi-Qubit
cx q[2], q[3];
ccx q[0], q[2], q[3];
cswap q[1], q[2], q[3];

// 5. Selective Barrier
barrier q[2], q[3];

// 6. Measurements (Mapping Qubits to Classical Bits)
c[0] = measure q[0];
c[1] = measure q[1];

// 7. NEW: Classical Control (If Blocks)
if (c[0]) {
    x q[2];
    inv @ t q[3];
}

// 8. NEW: Sequential If Blocks with different controls
if (c[1]) {
    h q[2];
    cx q[2], q[3];
}

OPENQASM 3.0;
include "qelib1.inc";
qreg q[3];
creg c[3];

h q[0];
cx q[0], q[1];
measure q[0] -> c[0];

OPENQASM 3.0;
include "stdgates.inc";

qubit[3] q;
bit[2] c;

c[0] = measure q[0];
c[1] = measure q[1];

// Applying a gate only if BOTH bits are 1
if (c[0] == 1 && c[1] == 1) {
    x q[2];
}

